["sm_first_safehouse_desc"] = "Sokaklarda ortalığı kasıp kavuracağın için ev diyebileceğin bir yere, güvenli bir eve ihtiyacın olacak. Tam sana göre bir yerim var. Çok gösterişli değil ama şimdilik idare eder. Oraya gidip bir bak; sonra para kazanmaya geçeriz.",
["sm_first_safehouse_name"] = "Güvenli Bir Sığınak",
["sm_first_safehouse_obj"] = "Güvenli evini en az bir kez ziyaret et.",
["sm_hoxton_revenge_desc"] = "Hoxton içerideki zamanını iyi kullandı. Daha hapishane pijamalarını çıkarmadan FBI karargâhına girip muhbir hakkında bulabildiği her şeyi aldı. İsim yok; federaller o kadar kurnaz. Ama muhbirin tutulduğu güvenli evin yeri var. Bitirme zamanı.",
["sm_hoxton_revenge_name"] = "Güvenli Evde Kurşunlar",
["sm_hoxton_revenge_obj"] = "Hoxton Revenge işini Çok Zor veya üzeri zorlukta tamamla.$NL;Bu görev için lobiden soygunun sonuna kadar oynamalısın.",
["sm_moving_up_desc"] = "Pekâlâ, insanların seni izlediğini daha önce söylemiştim. Özellikle bir adam seninle ilgileniyor. Bu yeni bağlantıyla büyük bir işimiz olabilir ama aklındaki iş zor olacak. Hazırlanmalısın.",
["sm_moving_up_desc_old"] = "Tamam, daha önce insanların seni izlediğini söylemiştim. Özellikle bir adam seninle ilgileniyor. Bu yeni bağlantıyla büyük bir işe girişebiliriz ama aklındaki iş zor olacak. Hazırlanman gerekiyor. Biraz daha hazır olduğunda geri gel, ben de gerekeni ayarlarım.",
["sm_moving_up_name"] = "Dünyada Yükselmek",
